#!/usr/bin/env bash
# SessionStart hook for qwickapps-sop plugin
# Outputs SOP configuration that maps SDLC abstract variables to QwickApps MCP tools.
# The SDLC plugin references these variables; this hook resolves them.

set -euo pipefail

sop_config="<IMPORTANT>\nThe qwickapps-sop plugin is active. SOP variables are configured below.\n\nWhen SDLC skills reference SOP variables (e.g. KB_CREATE_DOCUMENT, CTX_STORE_ISSUE),\nresolve them using this configuration.\n\n<sop-config>\n## Knowledge Base — Document Storage and Retrieval\n## Backend: Confluence via mcp__qwickapps__ MCP tools\n\nKB_CREATE_DOCUMENT = mcp__qwickapps__create_document\n  # Parameters: title (string), type (enum), content (string), labels (array), spaceId (optional)\n  # Types: frd, architecture, spike, adr, review, whiteboard, spec\n\nKB_GET_DOCUMENT = mcp__qwickapps__get_document\n  # Parameters: document_id (string)\n\nKB_LIST_DOCUMENTS = mcp__qwickapps__list_documents\n  # Parameters: type (optional enum), spaceId (optional), status (optional), limit, offset\n\nKB_SEARCH_DOCUMENTS = mcp__qwickapps__search_documents\n  # Parameters: q (string), type (optional enum), spaceId (optional), limit\n\nKB_UPDATE_DOCUMENT = mcp__qwickapps__update_document\n  # Parameters: document_id (string), title (optional), content (optional), labels (optional)\n\nKB_DELETE_DOCUMENT = mcp__qwickapps__delete_document\n  # Parameters: document_id (string)\n\n## Issue Context — Working Memory for Issues\n## Backend: Projects API item context via mcp__qwickapps__\n\nCTX_STORE_ISSUE = mcp__qwickapps__add_item_context\n  # Parameters: item_id (uuid), type (enum: spike, file, screenshot, link, note), content (string)\n  # Use type: \"note\" for issue investigation context\n\nCTX_GET_ISSUE = mcp__qwickapps__list_item_context\n  # Parameters: item_id (uuid)\n  # Returns all context entries attached to an item\n\nCTX_ISSUE_KEY_FORMAT = {repo}-issue-{N}-context\n  # Pattern for naming issue context entries\n\n## Sprint Management\n## Sprint artifacts stored as documents with labels for retrieval\n\nSPRINT_HANDOFF_STORE = mcp__qwickapps__create_document\n  # type: \"spike\", labels: [\"sprint-handoff\", \"sprint-{N}\"]\n  # title: \"Sprint {N} Handoff - {project}\"\n\nSPRINT_PLAN_STORE = mcp__qwickapps__create_document\n  # type: \"spike\", labels: [\"sprint-plan\", \"sprint-{N}\"]\n  # title: \"Sprint {N} Plan - {project}\"\n\nSPRINT_HANDOFF_GET = mcp__qwickapps__search_documents\n  # q: \"sprint handoff\", type: \"spike\"\n  # Or search by label: sprint-handoff\n\nSPRINT_KEY_FORMAT = sprint-{N}-handoff\n  # Naming pattern for sprint artifacts\n\n## Document Types\n## Maps abstract document categories to Confluence page types\n\nDOC_TYPE_SPIKE = spike\nDOC_TYPE_ADR = adr\nDOC_TYPE_FRD = frd\nDOC_TYPE_DESIGN = architecture\nDOC_TYPE_REVIEW = review\nDOC_TYPE_SPEC = spec\n\n## Audit Trail\n## Backend: Projects API journal via mcp__qwickapps__\n\nAUDIT_LOG = mcp__qwickapps__create_journal\n  # Parameters: agent (string), event (enum), goal_id (optional), item_id (optional), payload (optional)\n  # Events: goal_created, item_created, item_completed, item_blocked, comment_added, etc.\n\n## Worktree — Branch Isolation\n## QwickApps monorepo requires worktree-driven development\n\nWORKTREE_ENFORCED = true\nWORKTREE_SCRIPT = .claude/scripts/create-worktree.sh\n  # Usage: .claude/scripts/create-worktree.sh <name> [base-branch]\n  # Creates worktree at ../qwickapps-wt-<name>\n  # Copies .env files, .claude/settings.local.json, runs pnpm install\n\nWORKTREE_PREFIX = qwickapps-wt-\nPROTECTED_BRANCHES = main,dev\nPACKAGE_MANAGER = pnpm\n\n## Project Management\n## Backend: Projects API goals/items via mcp__qwickapps__\n\nPM_CREATE_GOAL = mcp__qwickapps__create_goal\nPM_LIST_GOALS = mcp__qwickapps__list_goals\nPM_CREATE_ITEM = mcp__qwickapps__create_item\nPM_UPDATE_ITEM = mcp__qwickapps__update_item\nPM_LIST_ITEMS = mcp__qwickapps__list_items\n\n## Secrets\n## Backend: Secrets API via mcp__qwickapps__\n\nSECRETS_GET = mcp__qwickapps__get_secret\nSECRETS_LIST = mcp__qwickapps__list_secrets\nSECRETS_SET = mcp__qwickapps__set_secret\n</sop-config>\n</IMPORTANT>"

cat <<EOF
{
  "additional_context": "${sop_config}",
  "hookSpecificOutput": {
    "hookEventName": "SessionStart",
    "additionalContext": "${sop_config}"
  }
}
EOF

exit 0
